#include <math.h>

int main() {
    int n;
    double sum = 0.0;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        double calificacion;
        scanf("%lf", &calificacion);
        sum += calificacion;
    }
    double promedio = sum / n;
    printf("%.2f\n", round(promedio));
    return 0;
}

