#include <stdio.h>

int main() {
    int n;
    double sum_aprobados = 0.0;
    int count_aprobados = 0;

    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        double calificacion;
        scanf("%lf", &calificacion);
        if (calificacion >= 6.0) {
            count_aprobados++;
            sum_aprobados += calificacion;
        }
    }

    if (count_aprobados > 0) {
        printf("%d %.2f\n", count_aprobados, sum_aprobados / count_aprobados);
    } else {
        printf("0 0.00\n");
    }
    return 0;
}
